var _ HotelProductRepository = (*GormHotelProductRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in the Unit's transaction on
// Commit.
type gormBatch struct {
	u         *repox.Unit
	db        *gorm.DB
	retention time.Duration
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *gormBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// CreateHotelProduct queues a create and returns the name the record will have.
func (b *gormBatch) CreateHotelProduct(parent string, in *hotel_productv1.HotelProduct) (string, error) {
	r := &GormHotelProductRepository{DB: b.db}
	m, named, err := r.newRow(parent, in)
	if err != nil {
		return "", err
	}
	var locks []string
	if k, ok := any(m).(interface{ NoOverlapKeys() []string }); ok {
		locks = k.NoOverlapKeys()
	}
	queueHotelProductReferences(b.u, named, nil)
	b.u.QueueGorm(locks, func(ctx context.Context, tx *gorm.DB) error {
		return r.insertTx(ctx, tx, named, m)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/HotelProduct", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateHotelProduct queues Update; in.Etag, when set, guards it, and a guard
// that fails rolls the whole batch back.
func (b *gormBatch) UpdateHotelProduct(in *hotel_productv1.HotelProduct, paths []string) {
	r := &GormHotelProductRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueHotelProductReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/HotelProduct", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getHotelProduct)})
}

